function renderValues(filter=''){const f=currentFeature;if(!f)return;const rows=f.measurements.filter(r=>r.label.toLowerCase().includes(filter.toLowerCase())),page=rows.slice(sourcePage*20,(sourcePage+1)*20);document.querySelector('#value-table').innerHTML='<div class="table-wrap"><table><thead><tr><th>'+t('sourceLabel')+'</th><th class="right">'+t('value')+'</th><th>'+t('state')+'</th></tr></thead><tbody>'+page.map(r=>'<tr><td><a class="mono" href="'+route('source/'+f.dataset.cohort+'/'+encodeURIComponent(r.label))+'">'+e(r.label)+'</a></td><td class="right mono">'+e(exactValue(r.value))+'</td><td><span title="'+e(r.state)+'" class="state '+(r.value===null?'missing':'')+'">'+e(stateName(r.state))+'</span></td></tr>').join('')+'</tbody></table></div><div class="result-bar"><span>'+n(rows.length)+' '+c('source labels · exact channel values','个来源标签 · 精确通道值')+'</span><div>'+(sourcePage?'<button class="btn small" data-values-prev>← '+t('previous')+'</button> ':'')+((sourcePage+1)*20<rows.length?'<button class="btn small" data-values-next>'+t('next')+' →</button>':'')+'</div></div>';}
function coverage(d){const s=stateCounts(d.state_counts);return '<div class="coverage-row"><div><a href="'+route('browse',{cohort:d.cohort,type:d.kind,history:['history','preview'].includes(d.role)?'1':'',audit:d.role==='audit'?'1':''})+'">'+e(featureName(d))+'</a><span>'+(s.total?(100*s.measured/s.total).toFixed(1):0)+'% '+c('observed','实测')+'</span></div><div class="coverage-track"><span style="width:'+(s.total?100*s.measured/s.total:0)+'%"></span><span style="width:'+(s.total?100*s.missing/s.total:0)+'%"></span></div></div>';}
