async function source(cohort,label){const result=await api(query('source',{cohort,label}));main.innerHTML='<div class="crumbs"><a href="'+route('studies/'+cohort)+'">'+e(studyName(cohort))+'</a> / '+t('sourceLabel')+'</div>'+top(label,c('View-specific QC for this source analysis label.','该来源分析标签在各特征视图中的质控记录。'),t('sourceLabel'))+note(sourceIdentity()+' '+c('Clinical groups are not inferred from label prefixes.','不根据标签前缀推断临床分组。'))+metadataSource(result.metadata,cohort)+'<div class="two-columns section-gap">'+result.items.map(({dataset:d,observation:o})=>'<section class="card"><h2>'+e(featureName(d))+'</h2>'+pill(d)+'<p class="mono muted">'+e(o.id)+'</p>'+(Object.keys(o.sample_measurements||{}).length?'<h3>'+t('sampleMetrics')+'</h3><dl class="definition">'+Object.entries(o.sample_measurements).map(([key,value])=>definition(fieldName(key),sampleValue(value))).join('')+'</dl>':'')+(o.qc.length?'<div class="table-wrap"><table><thead><tr><th>'+t('qc')+'</th><th>'+t('value')+'</th><th>'+t('status')+'</th></tr></thead><tbody>'+o.qc.map(q=>'<tr><td title="'+e(q.metric)+'">'+e(fieldName(q.metric))+'</td><td class="mono">'+e(q.value??t('notSupplied'))+'</td><td title="'+e(q.status)+'" class="small">'+e(['SOURCE_REPORTED','REPORTED'].includes(q.status)?t('reported'):q.status==='PASS'?t('pass'):q.status)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="small muted">'+c('No per-label QC fields were supplied for this view. See source selection and channel definitions.','此视图未提供标签级质控字段，请结合来源筛选规则及通道定义使用。')+'</p>')+'<div class="aside-links"><a class="btn small" href="'+route('browse',{cohort,type:d.kind})+'">'+t('browseView')+' →</a><a class="btn small" href="'+route('downloads',{dataset:d.id})+'">'+t('sourceMetadata')+' →</a></div></section>').join('')+'</div>';}
function statistics(p){const cohort=p.cohort||defaultCohort(),ds=datasetScope(catalog,{cohort}),s=catalog.studies.find(s=>s.id===cohort);if(!s)throw new Error(t('empty'));const max=Math.max(...ds.map(d=>d.features));main.innerHTML=top(c('Database statistics','数据库统计'),c('Live catalogue counts, separated by study, view and retained version.','实时目录计数，分别展示来源研究、特征视图与保留版本。'),c('Resource overview','资源概览'))+'<div class="feature-tabs">'+catalog.studies.map(x=>'<a class="'+(x.id===cohort?'active':'')+'" href="'+route('statistics',{cohort:x.id})+'">'+e(x.accession)+'</a>').join('')+'</div>'+metrics([[n(s.sources),t('sources')],[n(ds.length),t('views')],[n(ds.reduce((sum,d)=>sum+d.features,0)),t('features')],[n(s.versions),t('versions')]])+'<div class="two-columns"><section class="card"><h2>'+c('Feature rows by layer','各特征层的特征行数')+'</h2><p class="small muted">'+c('Active views only. Feature rows across layers are not unique gene counts.','仅统计当前视图；跨特征层的特征行数不等于独立基因数。')+'</p><div class="stat-bars">'+ds.map(d=>'<a href="'+route('browse',{cohort,type:d.kind})+'"><div><span>'+e(featureName(d))+'</span><b>'+n(d.features)+'</b></div><span class="stat-track"><i style="width:'+(100*d.features/max)+'%"></i></span></a>').join('')+'</div></section><section class="card"><h2>'+t('coverage')+'</h2><p class="small muted">'+c('States include all channels in each active release.','状态计数覆盖每个当前版本的全部通道。')+'</p><div class="legend"><span>'+t('observed')+'</span><span>NA</span></div>'+ds.map(coverage).join('')+'</section></div>'+note(sourceIdentity());}
