async function showReleasedBundle(dataset,channel){bundleManifest ||= await releaseJson('/public-downloads.json',abort?.signal);const b=readyBundle(bundleManifest,dataset,channel);if(!b)throw new Error(c('No frozen ZIP for this selection.','该选择没有对应冻结ZIP。'));const target=document.querySelector('#download-job');if(!target)return;target.innerHTML='<div class="job"><strong>'+t('ready')+'</strong><p>'+e(b.kind+' · '+b.column)+' · '+bytes(b.bytes)+'</p><a class="btn primary" href="'+e(b.url)+'">'+t('zip')+' ↓</a><p class="hash">SHA-256<br>'+e(b.sha256)+'</p><p>'+n(b.features)+' '+t('features')+' · '+n(b.source_labels)+' '+t('columns')+'</p></div>';}
async function pollJob(id){const value=await api('downloads/'+id),target=document.querySelector('#download-job');if(!target)return;if(value.status==='ready')target.innerHTML='<div class="job"><strong>'+t('ready')+'</strong><p>'+e(value.filename)+' · '+bytes(value.bytes)+'</p><a class="btn primary" href="'+e(value.url)+'">'+t('zip')+' ↓</a><p class="hash">SHA-256<br>'+e(value.sha256)+'</p><p>'+c('Includes the full matrix and '+(value.files.length-1)+' supporting files.','包含完整矩阵及 '+(value.files.length-1)+' 份配套文件。')+'</p></div>';else if(value.status==='failed')target.innerHTML='<div class="error"><h2>'+t('failedBundle')+'</h2><p>'+e(c(value.step,'生成失败，来源数据未改动。可重新提交相同选择。'))+'</p></div>';else{target.innerHTML='<div class="job progress"><strong>'+t(value.status==='queued'?'queued':'building')+'</strong><p>'+c('The source matrix, annotation and checksums are being prepared.','正在准备来源矩阵、注释及校验清单。')+'</p><p>'+n(value.files_completed)+' '+c('files prepared.','份文件已完成。')+'</p></div>';pollTimer=setTimeout(()=>pollJob(id).catch(error=>{if(error.name!=='AbortError'&&target.isConnected)target.innerHTML='<div class="error"><p>'+e(error.message)+'</p><button class="btn small" data-job-retry="'+e(id)+'">'+t('checkAgain')+'</button></div>';}),2000);}}
function methods(p){
  if(publicMode){renderPublicMethods(main,catalog,p);return;}
  const sections=[['start','guideStart'],['processing','guideProcessing'],['units','guideUnits'],['identity','guideIdentity'],['versions','guideVersions'],['downloads','guideDownloads'],['reference','guideReferences']];
  main.innerHTML=top(t('help'),c('Understand the measurements and follow the evidence behind each feature view.','理解各类测量，沿来源证据使用和复现特征视图。'),c('Data guide','数据使用指南'))+'<div class="docs-grid"><aside class="docs-nav">'+sections.map(([id,key])=>'<a href="'+route('methods',{section:id})+'" class="'+((p.section||'start')===id?'active':'')+'">'+t(key)+'</a>').join('')+'</aside><article class="docs">'+
    '<section id="guide-start"><h2>'+t('guideStart')+'</h2><ol><li>'+c('Choose a source study and feature layer in Browse. Search a native ID or a source-derived gene name.','在“特征浏览”中选择来源研究与特征层，检索原生 ID 或来源注释中可用的基因名。')+'</li><li>'+c('Open a feature, choose one channel and inspect its unit, distribution and exact values.','打开特征详情并选择测量通道，查看单位、数值分布及精确值表。')+'</li><li>'+c('Follow a source label to its view-specific QC records.','点击来源标签，查看其在各视图中的质控记录。')+'</li><li>'+c('Download a feature TSV or a full matrix bundle with annotation and provenance.','下载单特征 TSV，或包含完整矩阵、注释与来源信息的 ZIP 包。')+'</li></ol><p>'+c('The default cancer373 catalogue selects 14 unified final feature views. The full gene-plus-repeat table is an audit view. Historical versions remain accessible through explicit controls.','默认 cancer373 目录包含 14 个统一最终特征视图；基因与重复元件完整表属于审计视图。历史版本可通过相应开关访问。')+'</p><a class="btn primary" href="'+route('browse')+'">'+t('browse')+' →</a></section>'+
    '<section id="guide-processing"><h2>'+t('guideProcessing')+'</h2><p>'+c('Each layer retains its source definition. The unified registry selects a version and channel for each final layer; different measurements are not pooled onto one expression scale.','各特征层保留其来源定义。统一清单为每个最终特征层指定版本与通道，不将不同测量混合成同一表达尺度。')+'</p><div class="table-wrap"><table><thead><tr><th>'+t('featureView')+'</th><th>'+c('Interpretation','含义')+'</th></tr></thead><tbody>'+catalog.datasets.filter(d=>d.role==='final').map(d=>'<tr><td>'+e(featureName(d))+'</td><td>'+e(featureDescription(d))+'</td></tr>').join('')+'</tbody></table></div><h3>'+c('Exploratory selection','探索性筛选')+'</h3><p>'+c('AS, editing, RNA-variant and fusion final tables use whole-cohort exploratory QC. Predictive evaluation must fit selection inside the training fold. These matrices do not establish clinical biomarker performance.','AS、RNA 编辑、RNA 变异及融合最终表采用整体队列探索性质控。预测模型评估应在训练折内重新完成特征筛选。这些矩阵本身不证明临床标志物性能。')+'</p><h3>'+c('Allelic expression','等位基因表达')+'</h3><p>'+c('The cancer373 final ASE value is abs(0.5 − ref / (ref + alt)). Source total allele support must exceed 15; selected sites have at most three missing labels among 373. The independent cohort retains its own recorded rules.','cancer373 最终 ASE 值为 abs(0.5 − ref / (ref + alt))。来源要求等位基因总支持数大于 15，并保留 373 个标签中缺失数不超过 3 的位点。独立队列使用其自身记录的规则。')+'</p></section>'+
    '<section id="guide-units"><h2>'+t('guideUnits')+'</h2><p>'+c('Counts, TPM, CPM, RPM, coverage, PSI, VAF and imbalance indices describe different quantities. Each chart uses one channel and one unit.','计数、TPM、CPM、RPM、覆盖度、PSI、VAF 及不平衡指标描述不同的量。每幅图只展示一个通道及其单位。')+'</p><ul><li>'+c('Observed zero is a measured value retained in summaries and downloads.','实测零值是明确的测量结果，在统计与下载中保留。')+'</li><li>'+c('NA is unavailable, including documented low-depth or QC-failing states. It is excluded from numeric distributions.','NA 表示不可用值，包括已有记录的低深度或质控未通过状态，缺失值不纳入数值分布。')+'</li><li>'+c('Unreported layers are unavailable and are not zero-filled. Estimated fragment counts may be fractional.','未提供的特征层记为不可用，不补成零；估计片段数可以为小数。')+'</li><li>'+c('RNA variants and fusions remain source candidates; RNA alone does not establish paired-DNA somatic status or independently validated fusion biology.','RNA 变异与融合保留来源候选性质，单凭 RNA 数据不能确认配对 DNA 的体细胞状态或独立验证的融合生物学。')+'</li></ul><p>'+c('The RAG source file named TPM represents library-sum CPM. RNA-peak coordinates belong to RNA reference sequences, rather than genomic browser intervals.','来源 RAG 文件虽命名为 TPM，实际按文库总量归一化的 CPM 登记。RNA 富集峰坐标属于 RNA 参考序列，不作为基因组浏览器区间解释。')+'</p></section>'+
    '<section id="guide-identity"><h2>'+t('guideIdentity')+'</h2><p>'+e(sourceIdentity())+'</p><p>'+c('A source observation is identified within its study and reused across that study’s views. Version, feature-row and source-label counts are separate. Disease-like prefixes are not converted into confirmed clinical groups.','来源观察在所属研究内标识，并在该研究的各特征视图间复用。版本数、特征行数和来源标签数分别统计，不将类似疾病名称的标签前缀转化为已确认的临床分组。')+'</p></section>'+
    '<section id="guide-versions"><h2>'+t('guideVersions')+'</h2><p>'+c('The database retains '+catalog.versions+' immutable private versions. A feature revision and channel identify exact values. The unified collection selects 14 final views and one audit view; earlier versions remain available.','数据库保留 '+catalog.versions+' 个不可变私有版本。特征修订与通道共同确定具体测量值。统一集合指定 14 个最终视图及 1 个审计视图，并保留早期来源版本。')+'</p><p>'+c('Source and reference hashes accompany feature pages and downloads. Available QC is retained without silently removing low-quality labels. Technical delivery does not establish biological validation.','特征页及下载包提供来源与参考哈希。保留可用的来源质控，不静默剔除低质量标签。技术交付验收不等同于生物学验证。')+'</p><p>'+c('Run-specific QC models, reports and selection audits for four advanced final views remain incompletely supplied. Rules, current configuration, hashes and selected annotation are retained; full independent reconstruction of those QC runs is not established.','四类高级最终视图的运行专用质控模型、报告及筛选审计文件在现有材料中仍不完整。已保留规则、当前配置、交付哈希及筛选注释，但尚不能独立重建这些完整的质控运行。')+'</p></section>'+
    '<section id="guide-downloads"><h2>'+t('guideDownloads')+'</h2><p>'+c('Each ZIP contains a complete single-channel matrix, annotation, source labels, QC, provenance, README and SHA-256 checksums. Frozen wide matrices retain original numeric text and NA. The small historical preview is reconstructed from stored measurements.','每个 ZIP 包含完整单通道矩阵、特征注释、来源标签、质控、来源信息、README 和 SHA-256 清单。冻结宽表保留原始数字文本与明确的 NA；早期小规模预览由已存测量重建。')+'</p><p>'+c('Background bundles are reused for the same version, channel and source-manifest identity. Large files support HTTP byte ranges. Exact feature TSVs are available on detail pages.','后台下载包仅在版本、通道及来源清单身份相同时复用。大文件支持 HTTP 字节范围下载，详情页还可导出完整单特征 TSV。')+'</p><p>'+c('Core sample metadata describe labels, groups, specimens and accession links. Optional extensions retain clinical and preparation fields with explicit unknowns. Full source files and curation differences are retained on the server. Language switching leaves exported data unchanged.','核心样本元数据包含标签、分组、标本与公开编号。扩展表保留临床及建库字段并明确标记未知项。完整来源文件与整理差异保留在后台。切换界面语言不改变导出数据。')+'</p></section>'+
    '<section id="guide-reference"><h2>'+t('guideReferences')+'</h2><p>'+c('Cite the original source study and version used. A resource citation will accompany a formal public release. Interface organization references cfOmics feature navigation, structured filters, linked tables and visualizations.','使用时应引用原始来源研究及具体数据版本，正式公开版本将提供资源引用。界面组织参考 cfOmics 的特征导航、结构化筛选、关联数据表和可视化布局。')+'</p><p><a href="https://doi.org/10.1093/nar/gkad777" target="_blank" rel="noopener noreferrer">cfOmics</a> · <a href="https://doi.org/10.1093/nar/gkab668" target="_blank" rel="noopener noreferrer">EVAtlas</a> · <a href="https://exrna-atlas.org/" target="_blank" rel="noopener noreferrer">exRNA Atlas</a></p></section></article></div>';
  if(p.section)setTimeout(()=>document.querySelector('#guide-'+CSS.escape(p.section))?.scrollIntoView({block:'start'}),0);
}
document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('[data-form]'))return;event.preventDefault();const values=Object.fromEntries(new FormData(form)),kind=form.getAttribute('data-form');if(kind==='home')location.hash=route('search',{cohort:defaultCohort(),q:values.q.trim()});if(kind==='gene')location.hash=route('genes',{gene:values.gene.trim(),cohort:values.cohort});if(kind==='browse')location.hash=route(form.getAttribute('data-target')||'browse',values);if(kind==='download'){const button=form.querySelector('button');button.disabled=true;try{if(publicMode){await showReleasedBundle(values.dataset,values.channel);return;}const job=await api('downloads',{method:'POST',body:JSON.stringify({dataset_id:values.dataset,channel_id:values.channel})});const next=route('downloads',{...values,job:job.id});if(location.hash===next)await pollJob(job.id);else location.hash=next;}catch(error){const target=document.querySelector('#download-job');if(target&&error.name!=='AbortError')target.innerHTML=note(error.message,true);}finally{button.disabled=false;}}});
document.addEventListener('change',event=>{const el=event.target,{parts,params}=parseRoute(location.hash),mode=parts[0]||'browse';if(el.matches('[data-filter]'))location.hash=route(mode,{...params,cohort:params.cohort||defaultCohort(),[el.dataset.filter]:el.checked?'1':'',dataset:'',cursor:''});if(el.matches('[data-channel]'))location.hash=route(parts.join('/'),{channel:el.value});if(el.matches('[data-qc-dataset]'))location.hash=route(parts.join('/'),{...params,dataset:el.value});if(el.matches('[data-page-size]'))location.hash=route(mode,{...params,limit:el.value,cursor:''});if(el.id==='cohort-select')location.hash=route(mode,{...params,cohort:el.value,q:el.form.querySelector('[name=q]').value,type:'',dataset:'',cursor:''});if(el.id==='type-select'){const version=document.querySelector('#version-select'),cohort=el.form.querySelector('[name=cohort]').value,choices=datasetScope(catalog,{...params,cohort,type:el.value});if(version)version.innerHTML='<option value="">'+t('allVersions')+'</option>'+choices.map(d=>'<option value="'+d.id+'">'+e(featureName(d))+' · '+e(versionLabel(d))+'</option>').join('');}if(el.matches('[data-download-dataset]'))location.hash=route('downloads',{dataset:el.value,history:params.history||''});if(el.id==='download-channel')location.hash=route('downloads',{...params,channel:el.value,job:''});if(el.matches('[data-download-history]')){const clear=!el.checked&&['history','preview'].includes(dsById(params.dataset)?.role);location.hash=route('downloads',{dataset:clear?'':params.dataset||'',channel:clear?'':params.channel||'',history:el.checked?'1':''});}});
document.addEventListener('input',event=>{if(event.target.matches('[data-value-search]')){sourcePage=0;renderValues(event.target.value);rememberLabels(event.target.value,0);}if(event.target.matches('[data-sources-search]')){sourceListPage=0;renderSources(event.target.value);rememberLabels(event.target.value,0);}});
document.addEventListener('click',event=>{if(event.target.closest('a.skip')){event.preventDefault();main.focus();main.scrollIntoView({block:'start'});return;}const el=event.target.closest('button');if(!el)return;if(el.matches('[data-retry]')){catalog=null;render();}if(el.matches('[data-back]'))history.back();if(el.matches('[data-values-prev]')){sourcePage--;renderValues(document.querySelector('[data-value-search]').value);rememberLabels(document.querySelector('[data-value-search]').value,sourcePage);}if(el.matches('[data-values-next]')){sourcePage++;renderValues(document.querySelector('[data-value-search]').value);rememberLabels(document.querySelector('[data-value-search]').value,sourcePage);}if(el.matches('[data-sources-prev]')){sourceListPage--;renderSources(document.querySelector('[data-sources-search]').value);rememberLabels(document.querySelector('[data-sources-search]').value,sourceListPage);}if(el.matches('[data-sources-next]')){sourceListPage++;renderSources(document.querySelector('[data-sources-search]').value);rememberLabels(document.querySelector('[data-sources-search]').value,sourceListPage);}if(el.matches('[data-job-retry]'))pollJob(el.dataset.jobRetry).catch(fail);if(el.matches('[data-export-page]')){const rows=[['native_feature_id','feature_revision_id','source_study','release_id','version'],...currentResults.map(f=>[f.native_id,f.id,studyName(f.cohort),f.dataset_id,dsById(f.dataset_id).version])],tsv=rows.map(r=>r.map(v=>String(v??'').replace(/[\t\r\n]/g,' ')).join('\t')).join('\n')+'\n',url=URL.createObjectURL(new Blob([tsv],{type:'text/tab-separated-values;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='cfrnadb-feature-catalog-page.tsv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
window.addEventListener('hashchange',()=>{window.scrollTo({top:0});render();});render();
